begin;
select plan(9);
insert into auth.users(id,email) values ('c0000000-0000-0000-0000-000000000001','transform-admin@example.test'),('c0000000-0000-0000-0000-000000000002','transform-worker@example.test');
insert into public.profiles(id,display_name,role,active) values ('c0000000-0000-0000-0000-000000000001','Admin','admin',true),('c0000000-0000-0000-0000-000000000002','Worker','collaborator',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000001',true);
select public.create_material('Original rods','units',0);
select public.create_material('Segments','units',0);
select public.adjust_warehouse_stock('c0000000-0000-0000-0000-000000000003',(select id from public.materials where name='Original rods'),2,'initial');
select lives_ok($$select public.transform_material('c0000000-0000-0000-0000-000000000004',(select id from public.materials where name='Original rods'),(select id from public.materials where name='Segments'),1,3,'cut')$$,'transform one rod');
select lives_ok($$select public.transform_material('c0000000-0000-0000-0000-000000000004',(select id from public.materials where name='Original rods'),(select id from public.materials where name='Segments'),1,3,'cut')$$,'retry transformation');
select is((select quantity from public.warehouse_balances where material_id=(select id from public.materials where name='Original rods')),1::numeric,'source reduced once');
select is((select quantity from public.warehouse_balances where material_id=(select id from public.materials where name='Segments')),3::numeric,'result increased once');
select throws_ok($$select public.transform_material('c0000000-0000-0000-0000-000000000005',(select id from public.materials where name='Original rods'),(select id from public.materials where name='Segments'),2,6,'cut')$$,'P0001','insufficient stock','cannot transform missing stock');
select is((select count(*) from public.material_transformations),1::bigint,'failed transform rolls back');
select is((select count(*) from public.inventory_movements),3::bigint,'initial and two transformation movements');
select throws_ok($$delete from public.material_transformations$$,'42501',null,'history cannot be deleted directly');
select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.transform_material('c0000000-0000-0000-0000-000000000005',null,null,1,3,'cut')$$,'42501','access denied','worker cannot transform');
select * from finish();
rollback;
